// 前綴積 × 後綴積：先存左邊乘積，再從右邊乘上右側乘積
// 時間複雜度: O(n)，空間複雜度: O(1)（不含輸出）
function productExceptSelf(nums) {
    const n = nums.length;
    const ans = new Array(n).fill(1);
    for (let i = 1; i < n; i++)
        ans[i] = ans[i - 1] * nums[i - 1]; // 左側乘積
    let right = 1;
    for (let i = n - 1; i >= 0; i--) {
        ans[i] *= right; // 乘上右側乘積
        right *= nums[i];
    }
    return ans;
}

