#include <vector>

class Solution {
public:
    /**
     * 方法二：空間優化 O(1)（推薦）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    std::vector<int> productExceptSelf(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> answer(n, 1);

        // 第一步：計算左側乘積
        int left = 1;
        for (int i = 0; i < n; i++) {
            answer[i] = left;
            left *= nums[i];
        }

        // 第二步：計算右側乘積並乘到 answer 上
        int right = 1;
        for (int i = n - 1; i >= 0; i--) {
            answer[i] *= right;
            right *= nums[i];
        }

        return answer;
    }

    /**
     * 方法一：使用兩個額外陣列
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    std::vector<int> productExceptSelf_twoArrays(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> left(n, 1);
        std::vector<int> right(n, 1);
        std::vector<int> answer(n);

        // 計算左側乘積
        for (int i = 1; i < n; i++) {
            left[i] = left[i - 1] * nums[i - 1];
        }

        // 計算右側乘積
        for (int i = n - 2; i >= 0; i--) {
            right[i] = right[i + 1] * nums[i + 1];
        }

        // 計算結果
        for (int i = 0; i < n; i++) {
            answer[i] = left[i] * right[i];
        }

        return answer;
    }
};

