     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public int[] productExceptSelf(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];

        // 第一步：計算左側乘積
        int left = 1;
        for (int i = 0; i < n; i++) {
            answer[i] = left;
            left *= nums[i];
        }

        // 第二步：計算右側乘積並乘到 answer 上
        int right = 1;
        for (int i = n - 1; i >= 0; i--) {
            answer[i] *= right;
            right *= nums[i];
        }

        return answer;
    }

    /**
     * 方法一：使用兩個額外陣列
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    public int[] productExceptSelf_twoArrays(int[] nums) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];
        int[] answer = new int[n];

        // 初始化
        left[0] = 1;
        right[n - 1] = 1;

        // 計算左側乘積
        for (int i = 1; i < n; i++) {
            left[i] = left[i - 1] * nums[i - 1];
        }

        // 計算右側乘積
        for (int i = n - 2; i >= 0; i--) {
            right[i] = right[i + 1] * nums[i + 1];
        }

        // 計算結果
        for (int i = 0; i < n; i++) {
            answer[i] = left[i] * right[i];
        }

        return answer;
    }
}

