// 前綴積 × 後綴積：先存左邊乘積，再從右邊乘上右側乘積
// 時間複雜度: O(n)，空間複雜度: O(1)（不含輸出）
int* productExceptSelf(int* nums, int numsSize, int* returnSize) {
    int n = numsSize;
    int* ans = malloc(sizeof(int) * n);
    ans[0] = 1;
    for (int i = 1; i < n; i++) ans[i] = ans[i - 1] * nums[i - 1];   // 左側乘積
    int right = 1;
    for (int i = n - 1; i >= 0; i--) {
        ans[i] *= right;                                            // 乘上右側乘積
        right *= nums[i];
    }
    *returnSize = n;
    return ans;
}

